{"version":3,"file":"chat.js","sources":["pages/chat/chat.vue","../../../Downloads/HBuilderX.5.07.2026041006/HBuilderX/plugins/uniapp-cli-vite/uniPage:/cGFnZXMvY2hhdC9jaGF0LnZ1ZQ"],"sourcesContent":["<template>\r\n  <view class=\"chat-page\">\r\n    <!-- AI 客服标题栏（仅 target=kefu 时显示） -->\r\n    <view v-if=\"isAI\" class=\"ai-bar\">\r\n      <uni-icons type=\"staff\" size=\"18\" color=\"#fff\"></uni-icons>\r\n      <text class=\"ai-bar-text\">AI 智能客服</text>\r\n      <text class=\"ai-bar-sub\">由 DeepSeek 提供支持</text>\r\n    </view>\r\n\r\n    <scroll-view scroll-y class=\"msg-list\" :scroll-into-view=\"bottomId\">\r\n      <view v-for=\"msg in msgs\" :key=\"msg.id\" :class=\"['msg-row', msg.isMe ? 'me' : 'other']\">\r\n        <view v-if=\"msg.loading\" class=\"bubble modern-card loading-bubble\">\r\n          <text class=\"dot\">···</text>\r\n        </view>\r\n        <view v-else class=\"bubble modern-card\">{{ msg.text }}</view>\r\n      </view>\r\n      <view id=\"bottom-mark\" style=\"height: 20rpx;\"></view>\r\n    </scroll-view>\r\n\r\n    <view class=\"input-bar modern-card\">\r\n      <uni-easyinput v-model=\"inputVal\" placeholder=\"发消息...\" :clearable=\"false\" :disabled=\"sending\" />\r\n      <button class=\"modern-btn send-btn\" :disabled=\"sending\" @click=\"send\">发送</button>\r\n    </view>\r\n  </view>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref, nextTick } from 'vue'\r\nimport { onLoad } from '@dcloudio/uni-app'\r\nimport { post } from '@/utils/request.js'\r\n\r\nconst inputVal = ref('')\r\nconst bottomId = ref('')\r\nconst sending  = ref(false)\r\nconst isAI     = ref(false)\r\n\r\nconst msgs = ref([\r\n  { id: 1, text: '你好，拼车还在吗？', isMe: true },\r\n  { id: 2, text: '在的，随时可以预订', isMe: false }\r\n])\r\n\r\nonLoad((options) => {\r\n  if (options.target === 'kefu') {\r\n    isAI.value = true\r\n    msgs.value = [{ id: Date.now(), text: '你好！我是 MUST-GO AI 智能客服，请问有什么可以帮助你？', isMe: false }]\r\n    uni.setNavigationBarTitle({ title: 'AI 智能客服' })\r\n  }\r\n})\r\n\r\nconst scrollToBottom = () => {\r\n  nextTick(() => { bottomId.value = 'bottom-mark' })\r\n}\r\n\r\nconst send = async () => {\r\n  const text = inputVal.value.trim()\r\n  if (!text || sending.value) return\r\n\r\n  // 添加用户消息\r\n  msgs.value.push({ id: Date.now(), text, isMe: true })\r\n  inputVal.value = ''\r\n  scrollToBottom()\r\n\r\n  // 普通聊天：不调用 AI\r\n  if (!isAI.value) return\r\n\r\n  // AI 客服：调用后端\r\n  sending.value = true\r\n  const loadingId = Date.now() + 1\r\n  msgs.value.push({ id: loadingId, text: '', isMe: false, loading: true })\r\n  scrollToBottom()\r\n\r\n  try {\r\n    const res = await post('/api/chat', { question: text })\r\n    const idx = msgs.value.findIndex(m => m.id === loadingId)\r\n    if (idx !== -1) msgs.value[idx] = { id: loadingId, text: res.reply, isMe: false }\r\n  } catch (e) {\r\n    const idx = msgs.value.findIndex(m => m.id === loadingId)\r\n    if (idx !== -1) msgs.value[idx] = { id: loadingId, text: '网络异常，请稍后重试', isMe: false }\r\n  } finally {\r\n    sending.value = false\r\n    scrollToBottom()\r\n  }\r\n}\r\n</script>\r\n\r\n<style lang=\"scss\" scoped>\r\n.chat-page { height: 100vh; display: flex; flex-direction: column; background: var(--pc-bg); }\r\n\r\n.ai-bar {\r\n  display: flex; align-items: center; gap: 12rpx;\r\n  background: var(--pc-primary); padding: 20rpx 30rpx;\r\n  .ai-bar-text { color: #fff; font-size: 28rpx; font-weight: bold; }\r\n  .ai-bar-sub  { color: rgba(255,255,255,.7); font-size: 22rpx; margin-left: auto; }\r\n}\r\n\r\n.msg-list { flex: 1; padding: 30rpx; }\r\n.msg-row { display: flex; margin-bottom: 40rpx; }\r\n.msg-row.me { justify-content: flex-end; }\r\n.bubble { padding: 20rpx 30rpx; max-width: 70%; word-break: break-all; }\r\n.msg-row.me .bubble { background: var(--pc-primary); color: #fff; }\r\n\r\n.loading-bubble { min-width: 80rpx; display: flex; align-items: center; justify-content: center; }\r\n.dot { font-size: 36rpx; color: var(--pc-sub); letter-spacing: 4rpx; animation: blink 1s infinite; }\r\n@keyframes blink { 0%,100%{opacity:1} 50%{opacity:.3} }\r\n\r\n.input-bar { display: flex; padding: 20rpx 30rpx 60rpx; gap: 20rpx; border-radius: 40rpx 40rpx 0 0; }\r\n.send-btn { width: 140rpx; height: 72rpx; line-height: 72rpx; font-size: 28rpx; margin: 0; }\r\n</style>\r\n","import MiniProgramPage from 'C:/Users/16947/CodeBuddy/MUST-Carpool-WeChat/MUST-GO/pages/chat/chat.vue'\nwx.createPage(MiniProgramPage)"],"names":["ref","onLoad","uni","nextTick","post"],"mappings":";;;;;;;;;;;;;;;;AA+BA,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,WAAWA,cAAG,IAAC,EAAE;AACvB,UAAM,UAAWA,cAAG,IAAC,KAAK;AAC1B,UAAM,OAAWA,cAAG,IAAC,KAAK;AAE1B,UAAM,OAAOA,cAAAA,IAAI;AAAA,MACf,EAAE,IAAI,GAAG,MAAM,aAAa,MAAM,KAAM;AAAA,MACxC,EAAE,IAAI,GAAG,MAAM,aAAa,MAAM,MAAO;AAAA,IAC3C,CAAC;AAEDC,kBAAM,OAAC,CAAC,YAAY;AAClB,UAAI,QAAQ,WAAW,QAAQ;AAC7B,aAAK,QAAQ;AACb,aAAK,QAAQ,CAAC,EAAE,IAAI,KAAK,IAAK,GAAE,MAAM,qCAAqC,MAAM,MAAK,CAAE;AACxFC,sBAAAA,MAAI,sBAAsB,EAAE,OAAO,UAAS,CAAE;AAAA,MAC/C;AAAA,IACH,CAAC;AAED,UAAM,iBAAiB,MAAM;AAC3BC,oBAAAA,WAAS,MAAM;AAAE,iBAAS,QAAQ;AAAA,MAAa,CAAE;AAAA,IACnD;AAEA,UAAM,OAAO,YAAY;AACvB,YAAM,OAAO,SAAS,MAAM,KAAM;AAClC,UAAI,CAAC,QAAQ,QAAQ;AAAO;AAG5B,WAAK,MAAM,KAAK,EAAE,IAAI,KAAK,IAAG,GAAI,MAAM,MAAM,MAAM;AACpD,eAAS,QAAQ;AACjB,qBAAgB;AAGhB,UAAI,CAAC,KAAK;AAAO;AAGjB,cAAQ,QAAQ;AAChB,YAAM,YAAY,KAAK,IAAG,IAAK;AAC/B,WAAK,MAAM,KAAK,EAAE,IAAI,WAAW,MAAM,IAAI,MAAM,OAAO,SAAS,KAAI,CAAE;AACvE,qBAAgB;AAEhB,UAAI;AACF,cAAM,MAAM,MAAMC,cAAI,KAAC,aAAa,EAAE,UAAU,MAAM;AACtD,cAAM,MAAM,KAAK,MAAM,UAAU,OAAK,EAAE,OAAO,SAAS;AACxD,YAAI,QAAQ;AAAI,eAAK,MAAM,GAAG,IAAI,EAAE,IAAI,WAAW,MAAM,IAAI,OAAO,MAAM,MAAO;AAAA,MAClF,SAAQ,GAAG;AACV,cAAM,MAAM,KAAK,MAAM,UAAU,OAAK,EAAE,OAAO,SAAS;AACxD,YAAI,QAAQ;AAAI,eAAK,MAAM,GAAG,IAAI,EAAE,IAAI,WAAW,MAAM,cAAc,MAAM,MAAO;AAAA,MACxF,UAAY;AACR,gBAAQ,QAAQ;AAChB,uBAAgB;AAAA,MACjB;AAAA,IACH;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;;ACjFA,GAAG,WAAW,eAAe;"}
